	"$schema": "node_modules/wrangler/config-schema.json",
	"name": "uploads-smart",
	"main": "src/index.ts",
	"compatibility_date": "2026-10-06",
	"compatibility_flags": ["nodejs_compat"],
	"observability": { "enabled": true },
	// Workers AI only through the org gateway: pass { gateway: { id: "git-next" } } on every env.AI.run call.
	"ai": { "binding": "AI" },
	// Shared R2 bucket for uploads (owner @acme/storage). Set API_KEY via `wrangler secret put API_KEY` (never inline).
	"r2_buckets": [{ "binding": "UPLOADS", "bucket_name": "acme-shared-uploads" }]
	// Add only resources from .gitnext/catalog.json. Forks must not bind production resources.
}

src/index.ts:
// uploads-smart: stores files in R2 and returns an AI-generated one-sentence
// description of each upload. PUT requires the shared API key; GET is public.

interface Env {
	AI: Ai;
	UPLOADS: R2Bucket;
	API_KEY: string;
}

/** Every model call goes through the org AI Gateway with git-next cost metadata. */
function gateway(task: string) {
	return { gateway: { id: "git-next", metadata: { repo: "uploads-smart", agent: "app", task } } };
}

// Object key is derived from the caller-supplied name so GET can look it up
// directly. (Catalog suggests <repo>/<yyyy>/<mm>/<uuid> for generic uploads,
// but this endpoint is explicitly name-addressed by its contract.)
function r2Key(name: string): string {
	return `uploads-smart/${encodeURIComponent(name)}`;
}

function isAuthorized(request: Request, env: Env): boolean {
	if (!env.API_KEY) return false;
	const header = request.headers.get("x-api-key") ?? request.headers.get("authorization")?.replace(/^Bearer\s+/i, "");
	return header === env.API_KEY;
}

async function describeUpload(env: Env, name: string, contentType: string, size: number): Promise<string> {
	const prompt =
		`A file named "${name}" (content-type: ${contentType || "unknown"}, ${size} bytes) was just uploaded. ` +
		"Write exactly one plain-English sentence describing what this upload most likely is. No preamble.";
	try {
		const result = (await env.AI.run("@cf/zai-org/glm-5.3-flash", { prompt }, gateway("describe-upload"))) as {
			response?: string;
		};
		return (result.response ?? "").trim() || "Uploaded file.";
	} catch {
		return "Uploaded file (description unavailable).";
	}
}

export default {
	async fetch(request: Request, env: Env): Promise<Response> {
		const url = new URL(request.url);

		if (url.pathname === "/health") return Response.json({ ok: true });

		const match = url.pathname.match(/^\/files\/([^/]+)$/);
		if (!match) return new Response("Not found", { status: 404 });
		const name = decodeURIComponent(match[1]);
		const key = r2Key(name);

		if (request.method === "PUT") {
			if (!isAuthorized(request, env)) return new Response("Unauthorized", { status: 401 });

			const body = await request.arrayBuffer();
			const contentType = request.headers.get("content-type") ?? "application/octet-stream";
			const description = await describeUpload(env, name, contentType, body.byteLength);

			await env.UPLOADS.put(key, body, {
				httpMetadata: { contentType },
				customMetadata: { name, description },
			});

			return Response.json({ name, size: body.byteLength, contentType, description });
		}

		if (request.method === "GET") {
			const object = await env.UPLOADS.get(key);
			if (!object) return new Response("Not found", { status: 404 });

			const headers = new Headers();
			object.writeHttpMetadata(headers);
			headers.set("etag", object.httpEtag);
			if (object.customMetadata?.description) headers.set("x-description", object.customMetadata.description);

			return new Response(object.body, { headers });
		}

		return new Response("Method not allowed", { status: 405 });
	},
} satisfies ExportedHandler<Env>;
